// Read-only window onto Supabase for the cloud routine.
//
// The routine cannot hold the service key: that key bypasses every RLS policy
// in the schema and belongs in n8n alone (Aditya's rule). So the key stays
// here and the routine asks by NAME for one of a fixed set of queries. It
// cannot compose SQL, cannot name a table, and cannot write anything.
const b = $('Webhook').first().json.body || {};
if (b.secret !== 'sv-dbread-2026-10-05-R4nK') { throw new Error('bad secret'); }

const s = (v) => String(v == null ? '' : v).replace(/[^A-Za-z0-9 .,&@:+_\-]/g, '').slice(0, 120);
const n = (v, d, max) => { const x = parseInt(v, 10); return isFinite(x) && x > 0 ? Math.min(x, max) : d; };

// Each entry is a complete PostgREST query. Only the marked values are
// caller-supplied, and every one is sanitised above.
const Q = {
  // Threads where an investor spoke last and nobody has answered.
  owed_replies: () =>
    'v_owed_replies?select=startup,investor,gist,kind,days_waiting,last_in,owner_name'
    + '&order=days_waiting.desc&limit=' + n(b.limit, 50, 200),

  // Recent inbound mail from investors, newest first.
  recent_inbound: () =>
    'mail_log?select=sent_at,from_email,subject,reply_gist,reply_kind,startup_id,investor_id'
    + '&direction=eq.in&investor_id=not.is.null'
    + '&sent_at=gte.' + encodeURIComponent(new Date(Date.now() - n(b.hours, 24, 168) * 3600000).toISOString())
    + '&order=sent_at.desc&limit=' + n(b.limit, 100, 400),

  // Everything said on one startup, both directions.
  startup_mail: () =>
    'mail_log?select=sent_at,direction,from_email,to_emails,subject,reply_gist,reply_kind,investor_id'
    + '&startup_id=eq.' + n(b.startup_id, 0, 99999)
    + '&order=sent_at.desc&limit=' + n(b.limit, 100, 400),

  // Meetings in a window, for the stage machine to place rows in time.
  meetings: () =>
    'meetings?select=scheduled_at,is_second,held,meet_link,in_book,startup_id,investor_id,startup_name,investor_name,notes'
    + '&superseded_by=is.null'
    + '&scheduled_at=gte.' + encodeURIComponent(new Date(Date.now() - n(b.days_back, 2, 30) * 86400000).toISOString())
    + '&scheduled_at=lte.' + encodeURIComponent(new Date(Date.now() + n(b.days_fwd, 14, 90) * 86400000).toISOString())
    + '&order=scheduled_at.asc&limit=' + n(b.limit, 200, 500),

  startups: () => 'startups?select=id,name,sector,stage,bucket,owner_name,status,ask_as_written&order=name.asc&limit=200',
  investors: () => 'investors?select=id,name,contact_person,email,status,sectors,stage_pref,cheque_as_written&order=name.asc&limit=400',
  heartbeat: () => 'task_heartbeat?select=task,last_run_at,note&task=eq.' + s(b.task || 'dealflow-state-machine'),
};

const want = String(b.query || '');
if (!Q[want]) { throw new Error('unknown query. allowed: ' + Object.keys(Q).join(', ')); }
return [{ json: { path: Q[want](), query: want } }];

